function Employee (){
   let Emp=[{
    Eid: 100,
    Ename: "max",
    Eage: 21,
    Gender:"male"
   },
   {
    Eid: 101,
    Ename: "maxi",
    Eage: 22,
    Gender:"female"
   },
   {
    Eid: 102,
    Ename: "ghost",
    Eage: 24,
    Gender:"male"
   },
   {
    Eid: 103,
    Ename: "dora",
    Eage: 23,
    Gender:"female"
   },
   {
    Eid: 104,
    Ename: "manan",
    Eage: 25,
    Gender:"male"
   }

]
return(
    <div>
        <table c>
            <thead>
                 <tr>
                    <th>
                        Id
                    </th>
                    <th>
                        Name
                    </th>
                    <th>
                        Age
                    </th>
                    <th>
                        Gender
                    </th>
                 </tr>
            </thead>
            <tbody>
                 {
                    Emp.map((e)=>{
                        return(
                            <tr>
                                <td>{e.Eid}</td>
                                <td>{e.Ename}</td>
                                <td>{e.Age}</td>
                                <td>{e.Gender}</td>
                            </tr>
                        )
                    })
                 }
            </tbody>
        </table>
    </div>
)
}
export default Employee
